47:     public class BotEngine
48:     {
49:         // P/Invoke for C++ DLL
50:         [DllImport("D2RBot.Engine.dll", CallingConvention = CallingConvention.Cdecl)]
51:         private static extern bool InitializeBot();
52: 
53:         [DllImport("D2RBot.Engine.dll", CallingConvention = CallingConvention.Cdecl)]
54:         private static extern bool StartBotEngine(string route);
55: 
56:         [DllImport("D2RBot.Engine.dll", CallingConvention = CallingConvention.Cdecl)]
57:         private static extern bool StopBotEngine();
58: 
59:         [DllImport("D2RBot.Engine.dll", CallingConvention = CallingConvention.Cdecl)]
60:         private static extern int GetBotStatus();
61: 
62:         [DllImport("D2RBot.Engine.dll", CallingConvention = CallingConvention.Cdecl)]
63:         private static extern void GetGameState(out IntPtr playerPos, out IntPtr nearbyMobs);
64: 
65:         public event Action<string, string>? OnLogMessage;
66:         public event Action<BotStatus>? OnStatusChanged;
67:         public event Action<RunStatistics>? OnRunCompleted;
68:         public event Action<LevelingStatistics>? OnLevelingUpdate;
69: 
70:         private BotStatus _currentStatus;
71:         private RunStatistics _statistics;
72:         private LevelingStatistics _levelingStats;
73:         private Timer? _statusTimer;
74:         private bool _isRunning;
75:         private BotMode _currentMode;
76:         private readonly string _logFilePath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "bot_debug.log");
77: 
78:         public BotEngine()
79:         {
80:             _currentStatus = new BotStatus { State = BotState.Idle, IsConnected = false };
81:             _statistics = new RunStatistics();
82:             _levelingStats = new LevelingStatistics { CurrentLevel = 1, CurrentExp = 0, ExpToNextLevel = 1000 };
83:             WriteLog($"BotEngine initialized. Log path: {_logFilePath}");
84:         }
85: 
86:         public void Start(string route, BotMode mode = BotMode.MFRuns)
87:         {
88:             try
89:             {
90:                 _currentMode = mode;
91: 
92:                 if (mode == BotMode.Leveling)
93:                 {
94:                     StartLeveling(route);
95:                     return;
96:                 }
97: 
98:                 OnLogMessage?.Invoke("Initializing bot engine...", "INFO");
99:                 bool initResult = InitializeBot();
100:                 OnLogMessage?.Invoke($"InitializeBot returned: {initResult}", "INFO");
101:                 
102:                 if (!initResult)
103:                 {
104:                     OnLogMessage?.Invoke("Warning: InitializeBot failed, but continuing...", "WARNING");
105:                 }
106: 
107:                 OnLogMessage?.Invoke("Starting bot engine...", "INFO");
108:                 bool startResult = StartBotEngine(route);
109:                 OnLogMessage?.Invoke($"StartBotEngine returned: {startResult}", "INFO");
110:                 
111:                 if (!startResult)
112:                 {
113:                     OnLogMessage?.Invoke("Warning: StartBotEngine failed, but continuing...", "WARNING");
114:                 }
115: 
116:                 // Mark as running regardless - the mouse movement thread is active
117:                 _isRunning = true;
118:                 _currentStatus.State = BotState.Running;
119:                 _currentStatus.IsConnected = true;
120:                 _currentStatus.LastUpdate = DateTime.Now;
121:                 
122:                 OnLogMessage?.Invoke($"Bot started on route: {route}", "INFO");
123:                 OnLogMessage?.Invoke("Movement active", "INFO");
124:                 OnLogMessage?.Invoke("STATUS: ONLINE", "INFO");
125:                 
126:                 // Invoke status change
127:                 OnStatusChanged?.Invoke(_currentStatus);
128:                 
129:                 _statusTimer = new Timer(_ => UpdateStatus(), null, TimeSpan.Zero, TimeSpan.FromSeconds(1));
130:             }
131:             catch (DllNotFoundException ex)
132:             {
133:                 OnLogMessage?.Invoke($"DLL not found: {ex.Message}", "ERROR");
134:             }
135:             catch (Exception ex)
136:             {
