using System;
using System.Collections.Generic;

namespace D2RBot.GUI.Services
{
    /// <summary>
    /// Core game data structures and enumerations for D2R
    /// </summary>

    // Player Classes
    public enum PlayerClass
    {
        Amazon = 0,
        Sorceress = 1,
        Necromancer = 2,
        Paladin = 3,
        Druid = 4,
        Assassin = 5
    }

    // Game Difficulty
    public enum Difficulty
    {
        Normal = 0,
        Nightmare = 1,
        Hell = 2
    }

    // Actor Type
    public enum ActorType
    {
        Player = 0,
        Monster = 1,
        Object = 2,
        Missile = 3,
        Item = 4,
        Tile = 5
    }

    // Player Position Structure
    public class PlayerPosition
    {
        public int X { get; set; }
        public int Y { get; set; }
        public int Room { get; set; }
        public int Level { get; set; }
    }

    // Player Stats
    public class PlayerStats
    {
        public uint Health { get; set; }
        public uint MaxHealth { get; set; }
        public uint Mana { get; set; }
        public uint MaxMana { get; set; }
        public uint Stamina { get; set; }
        public uint MaxStamina { get; set; }
        public uint Level { get; set; }
        public ulong Experience { get; set; }
    }

    // Monster/NPC Data
    public class Actor
    {
        public uint Type { get; set; }
        public uint ClassId { get; set; }
        public uint UniqueId { get; set; }
        public ushort X { get; set; }
        public ushort Y { get; set; }
        public uint Life { get; set; }
        public uint MaxLife { get; set; }
        public string Name { get; set; } = "";
        public bool IsAlive { get; set; }
    }

    // Item Structure
    public class Item
    {
        public uint Type { get; set; }
        public uint Quality { get; set; }
        public ushort X { get; set; }
        public ushort Y { get; set; }
        public long ItemAddress { get; set; }
        public string Name { get; set; } = "";
        public Dictionary<string, int> Properties { get; set; } = new Dictionary<string, int>();
    }

    // Game State
    public class GameState
    {
        public PlayerPosition PlayerPos { get; set; } = new PlayerPosition();
        public PlayerStats PlayerStats { get; set; } = new PlayerStats();
        public List<Actor> Monsters { get; set; } = new List<Actor>();
        public List<Item> Items { get; set; } = new List<Item>();
        public uint MapSeed { get; set; }
        public int Act { get; set; }
        public Difficulty Difficulty { get; set; }
        public bool InGame { get; set; }
        public DateTime LastUpdate { get; set; }
    }

    // Memory Offsets Container
    public class MemoryOffsets
    {
        // Base Game Offsets
        public IntPtr GameBaseOffset { get; set; }
        public IntPtr PlayerPointerOffset { get; set; }
        public IntPtr ActorTableOffset { get; set; }
        public IntPtr ItemTableOffset { get; set; }
        public IntPtr MapSeedOffset { get; set; }
        public IntPtr DifficultyOffset { get; set; }
        public IntPtr ActOffset { get; set; }

        // Player-related Offsets
        public IntPtr PlayerPositionOffset { get; set; }
        public IntPtr PlayerHealthOffset { get; set; }
        public IntPtr PlayerManaOffset { get; set; }
        public IntPtr PlayerLevelOffset { get; set; }
        public IntPtr PlayerExperienceOffset { get; set; }
        public IntPtr PlayerClassOffset { get; set; }
        public IntPtr PlayerNameOffset { get; set; }

        // Actor offsets
        public IntPtr ActorTypeOffset { get; set; }
        public IntPtr ActorClassIdOffset { get; set; }
        public IntPtr ActorUniqueIdOffset { get; set; }
        public IntPtr ActorXOffset { get; set; }
        public IntPtr ActorYOffset { get; set; }
        public IntPtr ActorHealthOffset { get; set; }
    }
}

