        /// Gets the base address of D2R.exe in memory
        /// </summary>
        public static IntPtr GetD2RBaseAddress(Process process)
        {
            if (process == null || process.HasExited)
                return IntPtr.Zero;

            return process.MainModule?.BaseAddress ?? IntPtr.Zero;
        }

        /// <summary>
        /// Validates if we have a valid connection to D2R
        /// </summary>
        public static bool ValidateD2RConnection(Process process, IntPtr baseAddress)
        {
            if (process == null || process.HasExited)
                return false;

            if (baseAddress == IntPtr.Zero)
                return false;

            return true;
        }

