        /// </summary>
        public static IntPtr PatternScan(Process process, IntPtr baseAddress, byte[] pattern, string mask, int maxScan = 0x1000000)
        {
            if (process == null || process.HasExited)
                return IntPtr.Zero;

            byte[] buffer = new byte[4096];
            int bytesRead = 0;

            for (long offset = 0; offset < maxScan; offset += buffer.Length)
            {
                try
                {
                    if (!Mem.ReadProcessMemory(process.Handle, baseAddress + (int)offset, buffer, buffer.Length, ref bytesRead))
                        continue;

                    for (int i = 0; i < bytesRead - pattern.Length; i++)
                    {
                        bool match = true;
                        for (int j = 0; j < pattern.Length; j++)
                        {
                            if (mask[j] == 'x' && buffer[i + j] != pattern[j])
                            {
                                match = false;
                                break;
                            }
                        }

                        if (match)
                            return baseAddress + (int)(offset + i);
                    }
                }
                catch
                {
                    continue;
                }
            }

            return IntPtr.Zero;
        }
    }
}

