using System;
using System.Diagnostics;
using System.Threading;
using System.Threading.Tasks;
using System.Collections.Generic;

namespace D2RBot.GUI.Services
{
    /// <summary>
    /// Core bot engine for Diablo 2 Resurrected
    /// Handles game loop, pathfinding, and automation
    /// </summary>
    public class BotCore
    {
        private readonly Mem _mem;
        private readonly GameReader _gameReader;
        private readonly OffsetScanner _offsetScanner;
        private readonly InputSimulator _inputSimulator;

        private Process? _game;
        private IntPtr _baseAddress;
        private MemoryOffsets _offsets;
        private bool _isRunning;
        private CancellationTokenSource? _cancellationTokenSource;

        public event Action<string, string>? OnLog;
        public event Action<GameState>? OnGameStateUpdated;
        public event Action<BotStatus>? OnStatusChanged;

        private BotStatus _status;

        public BotCore()
        {
            _mem = new Mem();
            _gameReader = new GameReader(_mem, new MemoryOffsets());
            _offsetScanner = new OffsetScanner(_mem);
            _inputSimulator = new InputSimulator();
            _offsets = new MemoryOffsets();
            _status = new BotStatus { State = BotState.Idle };
        }

        /// <summary>
        /// Initializes bot and attaches to D2R process
        /// </summary>
        public bool Initialize()
        {
            Log("Searching for D2R process...", "INFO");

            _game = ProcessScanner.FindD2RProcess();
            if (_game == null || _game.HasExited)
            {
                Log("D2R.exe not found. Please start the game.", "ERROR");
                return false;
            }

            _baseAddress = ProcessScanner.GetD2RBaseAddress(_game);
            if (_baseAddress == IntPtr.Zero)
            {
                Log("Failed to get D2R base address.", "ERROR");
                return false;
            }

            _mem.SetProcessHandle(_game.Handle);
            _mem.SetBaseAddress(_baseAddress);

            Log($"D2R process found: PID={_game.Id}, BaseAddress=0x{_baseAddress:X}", "INFO");

            // Scan for offsets
            Log("Scanning for memory offsets...", "INFO");
            _offsetScanner.Initialize(_game, _baseAddress);
            _offsets = _offsetScanner.ScanOffsets();
            _gameReader = new GameReader(_mem, _offsets);

            Log("Bot initialized successfully.", "SUCCESS");
            _status.State = BotState.Idle;
            _status.IsConnected = true;
            OnStatusChanged?.Invoke(_status);

            return true;
        }

        /// <summary>
        /// Starts the bot main loop
        /// </summary>
        public void Start(string route = "Cow Level")
        {
            if (_isRunning)
            {
                Log("Bot is already running.", "WARNING");
                return;
            }

            if (_game == null || _game.HasExited)
            {
                Log("Game process not found. Please initialize first.", "ERROR");
                return;
            }

            _isRunning = true;
            _cancellationTokenSource = new CancellationTokenSource();

            Log($"Starting bot on route: {route}", "INFO");
            _status.State = BotState.Running;
            OnStatusChanged?.Invoke(_status);

            // Start game loop on background thread
            Task.Run(() => GameLoop(_cancellationTokenSource.Token), _cancellationTokenSource.Token);
        }

        /// <summary>
        /// Main game loop
        /// </summary>
        private async Task GameLoop(CancellationToken cancellationToken)
        {
            try
            {
                while (!cancellationToken.IsCancellationRequested && _isRunning)
                {
                    if (_game.HasExited)
                    {
                        Log("Game process ended.", "WARNING");
                        Stop();
                        break;
                    }

                    // Read game state
                    var gameState = _gameReader.ReadGameState();
                    OnGameStateUpdated?.Invoke(gameState);

                    if (!gameState.InGame)
                    {
                        Log("Not in game.", "WARNING");
                        await Task.Delay(1000, cancellationToken);
                        continue;
                    }

                    // Process bot logic
                    await ProcessGameState(gameState, cancellationToken);

                    // Update loop rate (60 FPS = 16.66ms)
                    await Task.Delay(16, cancellationToken);
                }
            }
            catch (OperationCanceledException)
            {
                Log("Bot loop cancelled.", "INFO");
            }
            catch (Exception ex)
            {
                Log($"Bot loop error: {ex.Message}", "ERROR");
            }
            finally
            {
                _isRunning = false;
                _status.State = BotState.Idle;
                OnStatusChanged?.Invoke(_status);
            }
        }

        /// <summary>
        /// Process current game state and execute bot actions
        /// </summary>
        private async Task ProcessGameState(GameState state, CancellationToken cancellationToken)
        {
            if (state.PlayerStats.Health == 0)
            {
                Log("Player is dead. Stopping bot.", "WARNING");
                Stop();
                return;
            }

            // Simple MF run logic
            if (state.Monsters.Count > 0)
            {
                // Kill monsters
                await AttackMonsters(state.Monsters, cancellationToken);
            }
            else if (state.Items.Count > 0)
            {
                // Pick up items
                await PickupItems(state.Items, cancellationToken);
            }
            else
            {
                // Move to next location or exit game
                await Task.Delay(100, cancellationToken);
            }
        }

        /// <summary>
        /// Attack nearby monsters
        /// </summary>
        private async Task AttackMonsters(List<Actor> monsters, CancellationToken cancellationToken)
        {
            if (monsters.Count == 0)
                return;

            // Simple targeting: closest monster
            var target = monsters[0];
            Log($"Attacking: {target.ClassId} at ({target.X}, {target.Y})", "DEBUG");

            // Move to target and attack
            _inputSimulator.MoveToPosition(target.X, target.Y);
            await Task.Delay(100, cancellationToken);
            _inputSimulator.ClickAttack();
        }

        /// <summary>
        /// Pick up nearby items
        /// </summary>
        private async Task PickupItems(List<Item> items, CancellationToken cancellationToken)
        {
            foreach (var item in items)
            {
                Log($"Picking up item: {item.Name}", "DEBUG");
                _inputSimulator.MoveToPosition(item.X, item.Y);
                await Task.Delay(50, cancellationToken);
                _inputSimulator.ClickPickup();
            }
        }

        /// <summary>
        /// Stops the bot
        /// </summary>
        public void Stop()
        {
            if (!_isRunning)
                return;

            Log("Stopping bot...", "INFO");
            _isRunning = false;
            _cancellationTokenSource?.Cancel();
            _status.State = BotState.Idle;
            OnStatusChanged?.Invoke(_status);
        }

        private void Log(string message, string level)
        {
            OnLog?.Invoke(message, level);
            System.Diagnostics.Debug.WriteLine($"[{level}] {message}");
        }

        public BotStatus GetStatus() => _status;
        public GameState GetCurrentGameState() => _gameReader.ReadGameState();
    }
}

