namespace D2RBot.GUI.Services
{
    /// <summary>
    /// Simulates mouse and keyboard input for the bot
    /// </summary>
    public class InputSimulator
    {
        [DllImport("user32.dll")]
        private static extern void mouse_event(uint dwFlags, uint dx, uint dy, uint cButtons, UIntPtr dwExtraInfo);

        [DllImport("user32.dll")]
        private static extern bool GetCursorPos(out POINT lpPoint);

        [DllImport("user32.dll")]
        private static extern bool SetCursorPos(int X, int Y);

        [DllImport("user32.dll")]
        private static extern void keybd_event(byte bVk, byte bScan, uint dwFlags, UIntPtr dwExtraInfo);

        [StructLayout(LayoutKind.Sequential)]
        private struct POINT
        {
            public int X;
            public int Y;
        }

        // Mouse event flags
        private const uint MOUSEEVENTF_MOVE = 0x0001;
        private const uint MOUSEEVENTF_LEFTDOWN = 0x0002;
        private const uint MOUSEEVENTF_LEFTUP = 0x0004;
        private const uint MOUSEEVENTF_RIGHTDOWN = 0x0008;
        private const uint MOUSEEVENTF_RIGHTUP = 0x0010;

        // Keyboard flags
        private const uint KEYEVENTF_KEYDOWN = 0x0000;
        private const uint KEYEVENTF_KEYUP = 0x0002;

        // Virtual key codes
        private const byte VK_SHIFT = 0x10;
        private const byte VK_CONTROL = 0x11;
        private const byte VK_ALT = 0x12;
        private const byte VK_SPACE = 0x20;
        private const byte VK_ESCAPE = 0x1B;
        private const byte VK_ENTER = 0x0D;

        private Random _random = new Random();

        /// <summary>
        /// Moves the cursor to specified position with some randomness
        /// </summary>
        public void MoveToPosition(int x, int y)
        {
            try
            {
                // Add slight randomization to avoid detection
                int offsetX = _random.Next(-2, 3);
                int offsetY = _random.Next(-2, 3);

                SetCursorPos(x + offsetX, y + offsetY);
                Thread.Sleep(_random.Next(50, 150));
            }
            catch { }
        }

        /// <summary>
        /// Performs a left mouse click
        /// </summary>
        public void LeftClick()
        {
            try
            {
                mouse_event(MOUSEEVENTF_LEFTDOWN, 0, 0, 0, UIntPtr.Zero);
                Thread.Sleep(_random.Next(20, 50));
                mouse_event(MOUSEEVENTF_LEFTUP, 0, 0, 0, UIntPtr.Zero);
                Thread.Sleep(_random.Next(50, 100));
            }
            catch { }
        }

        /// <summary>
        /// Performs a right mouse click
        /// </summary>
        public void RightClick()
        {
            try
            {
                mouse_event(MOUSEEVENTF_RIGHTDOWN, 0, 0, 0, UIntPtr.Zero);
                Thread.Sleep(_random.Next(20, 50));
                mouse_event(MOUSEEVENTF_RIGHTUP, 0, 0, 0, UIntPtr.Zero);
                Thread.Sleep(_random.Next(50, 100));
            }
            catch { }
        }

        /// <summary>
        /// Simulates attack action (right click)
        /// </summary>
        public void ClickAttack()
        {
            RightClick();
        }

        /// <summary>
        /// Simulates skill cast action (left click with skill selected)
        /// </summary>
        public void ClickSkill()
        {
            LeftClick();
        }

        /// <summary>
        /// Simulates item pickup (left click)
        /// </summary>
        public void ClickPickup()
        {
            LeftClick();
        }

        /// <summary>
        /// Presses a key
        /// </summary>
        public void PressKey(byte key)
        {
            try
            {
                keybd_event(key, 0, KEYEVENTF_KEYDOWN, UIntPtr.Zero);
                Thread.Sleep(_random.Next(50, 150));
                keybd_event(key, 0, KEYEVENTF_KEYUP, UIntPtr.Zero);
                Thread.Sleep(_random.Next(50, 100));
            }
            catch { }
        }

        /// <summary>
        /// Holds a key for specified duration
        /// </summary>
        public void HoldKey(byte key, int durationMs)
        {
            try
            {
                keybd_event(key, 0, KEYEVENTF_KEYDOWN, UIntPtr.Zero);
                Thread.Sleep(durationMs);
                keybd_event(key, 0, KEYEVENTF_KEYUP, UIntPtr.Zero);
            }
            catch { }
        }

        /// <summary>
        /// Types text
        /// </summary>
        public void TypeText(string text)
        {
            foreach (char c in text)
            {
                // Simplified - in reality would need to map chars to keys
                Thread.Sleep(_random.Next(50, 150));
            }
        }

        /// <summary>
        /// Gets current cursor position
        /// </summary>
        public (int X, int Y) GetCursorPosition()
        {
            GetCursorPos(out POINT p);
            return (p.X, p.Y);
        }

        /// <summary>
        /// Performs teleport (move + attack)
        /// </summary>
        public void Teleport(int x, int y)
        {
            // Simulate teleport by clicking on target location
            MoveToPosition(x, y);
            ClickSkill();
            Thread.Sleep(_random.Next(200, 400));
        }
    }
