using System;
using System.IO;
using System.Collections.Generic;
using System.Text.Json;

namespace D2RBot.GUI.Services
{
    /// <summary>
    /// Manages bot configuration and settings
    /// </summary>
    public class ConfigurationManager
    {
        private readonly string _configDir;
        private readonly string _offsetsFile;
        private readonly string _settingsFile;

        private Dictionary<string, string> _offsets;
        private Dictionary<string, object> _settings;

        public ConfigurationManager(string configDirectory = "")
        {
            _configDir = string.IsNullOrEmpty(configDirectory) 
                ? Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Config") 
                : configDirectory;

            _offsetsFile = Path.Combine(_configDir, "offsets.json");
            _settingsFile = Path.Combine(_configDir, "settings.json");

            _offsets = new Dictionary<string, string>();
            _settings = new Dictionary<string, object>();

            // Create config directory if it doesn't exist
            if (!Directory.Exists(_configDir))
            {
                Directory.CreateDirectory(_configDir);
            }

            LoadConfiguration();
        }

        /// <summary>
        /// Loads configuration from files
        /// </summary>
        public void LoadConfiguration()
        {
            LoadOffsets();
            LoadSettings();
        }

        /// <summary>
        /// Loads offsets from JSON file
        /// </summary>
        private void LoadOffsets()
        {
            try
            {
                if (File.Exists(_offsetsFile))
                {
                    string json = File.ReadAllText(_offsetsFile);
                    _offsets = JsonSerializer.Deserialize<Dictionary<string, string>>(json) ?? new Dictionary<string, string>();
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"Error loading offsets: {ex.Message}");
            }
        }

        /// <summary>
        /// Loads settings from JSON file
        /// </summary>
        private void LoadSettings()
        {
            try
            {
                if (File.Exists(_settingsFile))
                {
                    string json = File.ReadAllText(_settingsFile);
                    _settings = JsonSerializer.Deserialize<Dictionary<string, object>>(json) ?? GetDefaultSettings();
                }
                else
                {
                    _settings = GetDefaultSettings();
                    SaveSettings();
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"Error loading settings: {ex.Message}");
                _settings = GetDefaultSettings();
            }
        }

        /// <summary>
        /// Gets an offset value
        /// </summary>
        public IntPtr GetOffset(string key)
        {
            if (_offsets.TryGetValue(key, out var value))
            {
                try
                {
                    // Handle hex strings
                    if (value.StartsWith("0x", StringComparison.OrdinalIgnoreCase))
                    {
                        return (IntPtr)Convert.ToInt64(value, 16);
                    }
                    else
                    {
                        return (IntPtr)Convert.ToInt64(value);
                    }
                }
                catch { }
            }

            return IntPtr.Zero;
        }

        /// <summary>
        /// Sets an offset value
        /// </summary>
        public void SetOffset(string key, IntPtr value)
        {
            _offsets[key] = "0x" + value.ToInt64().ToString("X");
        }

        /// <summary>
        /// Gets a setting value
        /// </summary>
        public T GetSetting<T>(string key, T defaultValue = default)
        {
            if (_settings.TryGetValue(key, out var value))
            {
                try
                {
                    if (value is JsonElement element)
                    {
                        return JsonSerializer.Deserialize<T>(element.GetRawText()) ?? defaultValue;
                    }

                    return (T)Convert.ChangeType(value, typeof(T)) ?? defaultValue;
                }
                catch { }
            }

            return defaultValue;
        }

        /// <summary>
        /// Sets a setting value
        /// </summary>
        public void SetSetting<T>(string key, T value)
        {
            _settings[key] = value;
        }

        /// <summary>
        /// Saves configuration to files
        /// </summary>
        public void SaveConfiguration()
        {
            SaveOffsets();
            SaveSettings();
        }

        /// <summary>
        /// Saves offsets to JSON file
        /// </summary>
        private void SaveOffsets()
        {
            try
            {
                var options = new JsonSerializerOptions { WriteIndented = true };
                string json = JsonSerializer.Serialize(_offsets, options);
                File.WriteAllText(_offsetsFile, json);
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"Error saving offsets: {ex.Message}");
            }
        }

        /// <summary>
        /// Saves settings to JSON file
        /// </summary>
        private void SaveSettings()
        {
            try
            {
                var options = new JsonSerializerOptions { WriteIndented = true };
                string json = JsonSerializer.Serialize(_settings, options);
                File.WriteAllText(_settingsFile, json);
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"Error saving settings: {ex.Message}");
            }
        }

        /// <summary>
        /// Gets default settings
        /// </summary>
        private Dictionary<string, object> GetDefaultSettings()
        {
            return new Dictionary<string, object>
            {
                { "autoPickupLoot", true },
                { "teleportPreload", true },
                { "antiDetection", true },
                { "fpsTarget", 60 },
                { "logLevel", "INFO" },
                { "autoRestart", true },
                { "chickenHP", 30 },
                { "chickenMana", 10 },
                { "selectedRoute", "Cow Level" },
                { "selectedCharacter", "Sorceress" },
                { "selectedDifficulty", "Hell" }
            };
        }

        /// <summary>
        /// Converts MemoryOffsets to configuration
        /// </summary>
        public void SaveOffsets(MemoryOffsets memOffsets)
        {
            SetOffset("playerPointerOffset", memOffsets.PlayerPointerOffset);
            SetOffset("actorTableOffset", memOffsets.ActorTableOffset);
            SetOffset("itemTableOffset", memOffsets.ItemTableOffset);
            SetOffset("mapSeedOffset", memOffsets.MapSeedOffset);
            SetOffset("difficultyOffset", memOffsets.DifficultyOffset);
            SetOffset("actOffset", memOffsets.ActOffset);
            SetOffset("playerPositionOffset", memOffsets.PlayerPositionOffset);
            SetOffset("playerHealthOffset", memOffsets.PlayerHealthOffset);
            SetOffset("playerManaOffset", memOffsets.PlayerManaOffset);
            SetOffset("playerLevelOffset", memOffsets.PlayerLevelOffset);
            SetOffset("playerExperienceOffset", memOffsets.PlayerExperienceOffset);
            SetOffset("playerClassOffset", memOffsets.PlayerClassOffset);
            SetOffset("playerNameOffset", memOffsets.PlayerNameOffset);
            SetOffset("actorTypeOffset", memOffsets.ActorTypeOffset);
            SetOffset("actorClassIdOffset", memOffsets.ActorClassIdOffset);
            SetOffset("actorUniqueIdOffset", memOffsets.ActorUniqueIdOffset);
            SetOffset("actorXOffset", memOffsets.ActorXOffset);
            SetOffset("actorYOffset", memOffsets.ActorYOffset);
            SetOffset("actorHealthOffset", memOffsets.ActorHealthOffset);

            SaveOffsets();
        }

        /// <summary>
        /// Loads offsets into MemoryOffsets object
        /// </summary>
        public MemoryOffsets LoadOffsets()
        {
            return new MemoryOffsets
            {
                GameBaseOffset = GetOffset("gameBaseOffset"),
                PlayerPointerOffset = GetOffset("playerPointerOffset"),
                ActorTableOffset = GetOffset("actorTableOffset"),
                ItemTableOffset = GetOffset("itemTableOffset"),
                MapSeedOffset = GetOffset("mapSeedOffset"),
                DifficultyOffset = GetOffset("difficultyOffset"),
                ActOffset = GetOffset("actOffset"),
                PlayerPositionOffset = GetOffset("playerPositionOffset"),
                PlayerHealthOffset = GetOffset("playerHealthOffset"),
                PlayerManaOffset = GetOffset("playerManaOffset"),
                PlayerLevelOffset = GetOffset("playerLevelOffset"),
                PlayerExperienceOffset = GetOffset("playerExperienceOffset"),
                PlayerClassOffset = GetOffset("playerClassOffset"),
                PlayerNameOffset = GetOffset("playerNameOffset"),
                ActorTypeOffset = GetOffset("actorTypeOffset"),
