                ActorUniqueIdOffset = GetOffset("actorUniqueIdOffset"),
                ActorXOffset = GetOffset("actorXOffset"),
                ActorYOffset = GetOffset("actorYOffset"),
                ActorHealthOffset = GetOffset("actorHealthOffset")
            };
        }
    }
