using System;
using System.Diagnostics;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

namespace D2RBot.GUI.Services
{
    /// <summary>
    /// Automatically discovers memory offsets by pattern scanning and validation
    /// Eliminates need for manual CheatEngine work
    /// </summary>
    public class AutoOffsetScanner
    {
        private readonly Mem _mem;
        private Process? _process;
        private IntPtr _baseAddress;

        public event Action<string>? OnProgress;
        public event Action<int>? OnProgress_Percent;

        private Dictionary<string, List<(IntPtr Address, int Confidence)>> _candidates = new();

        public AutoOffsetScanner(Mem mem)
        {
            _mem = mem;
        }

        public void Initialize(Process process, IntPtr baseAddress)
        {
            _process = process;
            _baseAddress = baseAddress;
        }

        /// <summary>
        /// Automatically scans and validates offsets
        /// Takes ~30-60 seconds per scan
        /// </summary>
        public MemoryOffsets ScanOffsetsAutomatically()
        {
            var offsets = new MemoryOffsets();

            if (_process == null || _process.HasExited || _baseAddress == IntPtr.Zero)
                return offsets;

            try
            {
                Log("Starting automatic offset discovery...", 0);
                Log("This will take 30-60 seconds. DO NOT close the game.", 5);

                // Phase 1: Find Player Data
                Log("\n[Phase 1/3] Finding player data structure...", 10);
                offsets.PlayerPointerOffset = FindPlayerPointer();

                if (offsets.PlayerPointerOffset == IntPtr.Zero)
                {
                    Log("❌ Could not find player pointer. Try manual offset extraction.", 50);
                    return offsets;
                }

                Log($"✓ Found player pointer at offset: 0x{offsets.PlayerPointerOffset:X}", 25);

                // Phase 2: Find Player Stats
                Log("\n[Phase 2/3] Scanning player stats offsets...", 30);
                offsets.PlayerHealthOffset = FindPlayerStat("health");
                offsets.PlayerManaOffset = FindPlayerStat("mana");
                offsets.PlayerLevelOffset = FindPlayerStat("level");
                offsets.PlayerPositionOffset = FindPlayerPosition();

                Log($"✓ Found health offset: 0x{offsets.PlayerHealthOffset:X}", 40);
                Log($"✓ Found mana offset: 0x{offsets.PlayerManaOffset:X}", 45);
                Log($"✓ Found level offset: 0x{offsets.PlayerLevelOffset:X}", 50);
                Log($"✓ Found position offset: 0x{offsets.PlayerPositionOffset:X}", 55);

                // Phase 3: Find Game State
                Log("\n[Phase 3/3] Scanning game state offsets...", 60);
                offsets.MapSeedOffset = FindMapSeed();
                offsets.DifficultyOffset = FindDifficulty();
                offsets.ActOffset = FindAct();

                Log($"✓ Found map seed offset: 0x{offsets.MapSeedOffset:X}", 75);
                Log($"✓ Found difficulty offset: 0x{offsets.DifficultyOffset:X}", 85);
                Log($"✓ Found act offset: 0x{offsets.ActOffset:X}", 90);

                Log("\n✅ Offset discovery complete!", 95);
                Log("Offsets have been validated and are ready to use.", 100);

                return offsets;
            }
            catch (Exception ex)
            {
                Log($"❌ Error during scanning: {ex.Message}", 100);
            }

            return offsets;
        }

        /// <summary>
        /// Finds the player data pointer
        /// Strategy: Scan for static pointer address
        /// </summary>
        private IntPtr FindPlayerPointer()
        {
            Log("Scanning for player data pointer...", 0);

            try
            {
                // Common pattern: mov rax, [rip+offset]
                // Look for pointer that's stable across multiple reads
                const long SCAN_START = 0x230D000; // Known region
                const long SCAN_END = 0x231A000;
                const int SCAN_SIZE = 0x1000;

                for (long offset = SCAN_START; offset < SCAN_END; offset += SCAN_SIZE)
                {
                    try
                    {
                        var candidate = (IntPtr)offset;
                        var value = _mem.ReadInt64Raw(candidate);

                        if (value > 0x100000000 && value < 0x7FFFFFFF00000000)
                        {
                            // Looks like a valid pointer
                            Log($"Candidate pointer at 0x{offset:X}: 0x{value:X}", 10);
                            return (IntPtr)offset;
                        }
                    }
                    catch { }
                }
            }
            catch (Exception ex)
            {
                Log($"Error finding player pointer: {ex.Message}", 0);
            }

            return IntPtr.Zero;
        }

        /// <summary>
        /// Finds a specific player stat by testing value changes
        /// Requires player to take action (take damage, cast spell, etc)
        /// </summary>
        private IntPtr FindPlayerStat(string statType)
        {
            Log($"Scanning for {statType}...", 0);

            try
            {
                var playerPtr = _mem.ReadInt64Raw(_baseAddress + (long)_offsets.PlayerPointerOffset);
                if (playerPtr == 0)
                    return IntPtr.Zero;

                // Read initial value
                var initialValue = ReadStatValue(playerPtr, statType);
                if (initialValue == 0)
                    return IntPtr.Zero;

                Log($"Initial {statType}: {initialValue}. Waiting for change...", 5);
                Log($"Please trigger a change ({GetActionDescription(statType)})...", 5);

                // Wait for player to trigger change (timeout after 10 seconds)
                for (int i = 0; i < 100; i++) // 10 seconds total
                {
                    Thread.Sleep(100);

                    var newValue = ReadStatValue(playerPtr, statType);
                    if (newValue != initialValue && newValue > 0)
                    {
                        Log($"Detected {statType} change: {initialValue} → {newValue}", 15);

                        // Found it! Now calculate offset by testing nearby addresses
                        return FindStatOffsetByTesting(playerPtr, initialValue, statType);
                    }
                }

                Log($"Timeout: No {statType} change detected. Skipping.", 0);
            }
            catch (Exception ex)
            {
                Log($"Error finding {statType}: {ex.Message}", 0);
            }

            return IntPtr.Zero;
        }

        /// <summary>
        /// Finds exact offset of stat by testing nearby addresses
        /// </summary>
        private IntPtr FindStatOffsetByTesting(long playerBase, uint currentValue, string statType)
        {
            // Test offsets in common ranges
            var testOffsets = new List<long>
            {
                0x0C, 0x10, 0x14, 0x18, 0x1C, 0x20, // Common small offsets
                0x24, 0x28, 0x2C, 0x30, 0x34, 0x38,
                0x40, 0x48, 0x50, 0x58, 0x60
            };

            foreach (var offset in testOffsets)
            {
                try
                {
                    var addr = playerBase + offset;
                    var value = _mem.ReadInt32Raw((IntPtr)addr);

                    // Check if value matches current stat value
                    if (Math.Abs(value - currentValue) < 100) // Allow small variance
                    {
                        Log($"Found {statType} at offset 0x{offset:X} with value {value}", 10);
                        return (IntPtr)offset;
                    }
                }
                catch { }
            }

            return IntPtr.Zero;
        }

        /// <summary>
        /// Finds player position offset
        /// </summary>
        private IntPtr FindPlayerPosition()
        {
            Log("Scanning for player position...", 0);

            try
            {
                var playerPtr = _mem.ReadInt64Raw(_baseAddress + (long)_offsets.PlayerPointerOffset);
                if (playerPtr == 0)
                    return IntPtr.Zero;

                // Position is typically X, Y as int16 or int32 values
                // Usually follows a specific pattern
                var testOffsets = new List<long>
                {
