    /// <summary>
    /// Automatically discovers memory offsets by pattern scanning and validation
    /// Eliminates need for manual CheatEngine work
    /// </summary>
    public class AutoOffsetScanner
    {
        private readonly Mem _mem;
        private Process? _process;
        private IntPtr _baseAddress;

        public event Action<string>? OnProgress;
        public event Action<int>? OnProgress_Percent;

        private Dictionary<string, List<(IntPtr Address, int Confidence)>> _candidates = new();

        public AutoOffsetScanner(Mem mem)
        {
            _mem = mem;
