                {
                    0x30, 0x34, 0x38, 0x3C, 0x40, 0x44, 0x48, 0x4C, 0x50
                };

                foreach (var offset in testOffsets)
                {
                    try
                    {
                        var x = _mem.ReadInt16Raw((IntPtr)(playerPtr + offset));
                        var y = _mem.ReadInt16Raw((IntPtr)(playerPtr + offset + 2));

                        // Valid game position is roughly (0, 0) to (500, 500)
                        if (x > 0 && x < 1000 && y > 0 && y < 1000)
                        {
                            Log($"Found position at offset 0x{offset:X}: ({x}, {y})", 10);
                            return (IntPtr)offset;
                        }
                    }
                    catch { }
                }
            }
            catch (Exception ex)
            {
                Log($"Error finding position: {ex.Message}", 0);
            }

            return IntPtr.Zero;
        }

        /// <summary>
        /// Finds map seed (unique per game)
        /// </summary>
        private IntPtr FindMapSeed()
        {
            Log("Scanning for map seed...", 0);

