                        }
                    }
                    catch { }
                }
            }
            catch (Exception ex)
            {
                Log($"Error finding map seed: {ex.Message}", 0);
            }

            return IntPtr.Zero;
        }

        /// <summary>
        /// Finds difficulty (0=Normal, 1=Nightmare, 2=Hell)
        /// </summary>
        private IntPtr FindDifficulty()
        {
            Log("Scanning for difficulty...", 0);

            try
            {
                // Difficulty is typically near map seed, small value (0-2)
                const long GAME_STATE_BASE = 0x230D000;

                for (long offset = GAME_STATE_BASE; offset < GAME_STATE_BASE + 0x100; offset += 4)
