private void AutoScanOffsets_Click(object sender, RoutedEventArgs e)
{
    try
    {
        LogMessage("Starting automatic offset discovery...", "INFO");
        LogMessage("Make sure D2R.exe is running and you're in a game!", "WARNING");
        LogMessage("", "INFO");

        // Find D2R process
        var process = ProcessScanner.FindD2RProcess();
        if (process == null || process.HasExited)
        {
            LogMessage("❌ D2R.exe not found. Please start the game.", "ERROR");
            return;
        }

        var baseAddress = ProcessScanner.GetD2RBaseAddress(process);
        if (baseAddress == IntPtr.Zero)
        {
            LogMessage("❌ Failed to get D2R base address.", "ERROR");
            return;
        }

        LogMessage($"✓ D2R process found (PID: {process.Id})", "SUCCESS");

        // Initialize memory access
        var mem = new Mem();
        mem.SetProcessHandle(process.Handle);
        mem.SetBaseAddress(baseAddress);

        // Run auto-scan
        var scanner = new AutoOffsetScanner(mem);
        scanner.Initialize(process, baseAddress);
        scanner.OnProgress += msg => LogMessage(msg, "SCAN");
        scanner.OnProgress_Percent += pct =>
        {
            // Could update a progress bar here
        };

        LogMessage("\nPhase 1: Finding player pointer...", "INFO");
        LogMessage("Scanning memory regions...", "INFO");

        var offsets = scanner.ScanOffsetsAutomatically();

        if (offsets.PlayerPointerOffset == IntPtr.Zero)
        {
            LogMessage("\n❌ Auto-scan failed. Try manual offset extraction with CheatEngine.", "ERROR");
            return;
        }

        // Save offsets to config
        LogMessage("\n✓ All offsets found! Saving configuration...", "SUCCESS");

        var config = new ConfigurationManager();
        config.SaveOffsets(offsets);

        LogMessage("✅ Offsets saved to Config/offsets.json", "SUCCESS");
        LogMessage("\nYou can now click INITIALIZE to load these offsets.", "INFO");
    }
    catch (Exception ex)
    {
        LogMessage($"❌ Error: {ex.Message}", "ERROR");
    }
}

