private void TestMemoryHooks_Click(object sender, RoutedEventArgs e)
{
    try
    {
        LogMessage("Running memory hook tests...", "INFO");
        IntPtr resultPtr = RunMemoryHookTests();

        if (resultPtr == IntPtr.Zero)
        {
            LogMessage("Test failed - no result returned", "ERROR");
            return;
        }

        string? result = Marshal.PtrToStringAnsi(resultPtr);
        if (string.IsNullOrEmpty(result))
        {
            LogMessage("Test returned empty result", "ERROR");
            return;
        }

        LogMessage("=== MEMORY HOOK TEST RESULTS ===", "TEST");
        foreach (var line in result.Split('\n'))
        {
            if (!string.IsNullOrWhiteSpace(line))
            {
                LogMessage(line, "TEST");
            }
        }
        LogMessage("================================", "TEST");

        // Also show in a message box
        MessageBox.Show(result, "Memory Hook Test Results", MessageBoxButton.OK, MessageBoxImage.Information);
    }
    catch (Exception ex)
    {
        LogMessage($"Error running memory tests: {ex.Message}", "ERROR");
        MessageBox.Show($"Error: {ex.Message}\n\n{ex.StackTrace}", "Test Error", MessageBoxButton.OK, MessageBoxImage.Error);
    }
}

